import { Injectable } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';

import { CreateOfferingDTO } from './createOffering.dto.js';

@ValidatorConstraint({ name: 'FreeTrialAndCreditRule', async: false })
@Injectable()
export class FreeTrialAndCreditRule implements ValidatorConstraintInterface {
    validate(freeTrialLength: string, args: ValidationArguments) {
        const credit = (args.object as CreateOfferingDTO).prepaidCredit;

        if (freeTrialLength && credit) {
            return false;
        }

        return true;
    }

    defaultMessage() {
        return 'Free credit and a free trial cannot exist on the same offering';
    }
}

export function FreeTrialAndCredit(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'freeTrialAndCredit',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: FreeTrialAndCreditRule,
        });
    };
}
import { ValidatorConstraint } from 'class-validator';

@ValidatorConstraint({ name: 'value', async: false })
export class IsNumericStringGreaterThanOrEqualToZeroValidator {
    validate(value: string) {
        return !isNaN(Number(value)) && Number(value) >= 0;
    }

    defaultMessage() {
        return 'Invalid value: must be a number greater than or equal to zero in string format';
    }
}

@ValidatorConstraint({ name: 'value', async: false })
export class IsNumericStringGreaterToZeroValidator {
    validate(value: string) {
        return !isNaN(Number(value)) && Number(value) > 0;
    }

    defaultMessage() {
        return 'Invalid value: must be a number greater than zero in string format';
    }
}

// Validate numerical string less than or equal to 100
@ValidatorConstraint({ name: 'value', async: false })
export class IsNumericStringLessThanOrEqualToHundredValidator {
    validate(value: string) {
        return !isNaN(Number(value)) && Number(value) <= 100;
    }

    defaultMessage() {
        return 'Invalid value: must be a number less than or equal to 100 in string format';
    }
}

