export enum ValidBillingCycles {
    monthly = 'monthly',
    'annualToDate' = 'annualToDate',
    topUp = 'topUp',
}

/**
 * The default threshold used to determine when a customer wallet should be topped up.
 * The threshold is a multiplier of the `topUpAmount`.
 */
export const DEFAULT_TOP_UP_THRESHOLD = '0.2';

