import { Injectable } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';

import { CreateOfferingDTO, ValidBillingCycles } from './createOffering.dto.js';
import { OfferingType } from '../entities/OfferingType.js';

/**
 * Validates a top up offering. A top up offering must have a topUpAmount, and cannot be a subscription offering.
 */
@ValidatorConstraint({ name: 'TopUpBillingCycleRule', async: false })
@Injectable()
export class TopUpBillingCycleRule implements ValidatorConstraintInterface {
    validate(billingCycle: ValidBillingCycles, args: ValidationArguments) {
        const { topUpAmount, offeringType } = args.object as CreateOfferingDTO;
        if (billingCycle !== ValidBillingCycles.topUp) {
            return true;
        }
        if (offeringType === OfferingType.subscription) {
            return false;
        }
        if (topUpAmount === undefined || topUpAmount === null || `${topUpAmount}`.trim() === '') {
            return false;
        }
        if (isNaN(Number(topUpAmount)) || Number(topUpAmount) <= 0) {
            return false;
        }
        return true;
    }

    defaultMessage(args: ValidationArguments) {
        const { offeringType } = args.object as CreateOfferingDTO;
        if (offeringType === OfferingType.subscription) {
            return 'The topUp billing cycle is not supported for subscription offerings';
        }
        return 'topUpAmount is required, and must be a number greater than zero in string format, for offerings with a topUp billing cycle';
    }
}

/**
 * Validates that the top up fields are only used on offerings with a topUp billing cycle.
 */
@ValidatorConstraint({ name: 'TopUpFieldRule', async: false })
@Injectable()
export class TopUpFieldRule implements ValidatorConstraintInterface {
    validate(value: string, args: ValidationArguments) {
        const { billingCycle } = args.object as CreateOfferingDTO;
        if (value === undefined || value === null) {
            return true;
        }
        return billingCycle === ValidBillingCycles.topUp;
    }

    defaultMessage(args: ValidationArguments) {
        return `${args.property} is only supported on offerings with a topUp billing cycle`;
    }
}

export function TopUpBillingCycle(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'topUpBillingCycle',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TopUpBillingCycleRule,
        });
    };
}

export function TopUpField(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'topUpField',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TopUpFieldRule,
        });
    };
}

