@IsEnum(ValidBillingCycles)
@IsOptional()
@TopUpBillingCycle('billingCycle')
@ApiProperty({ enum: ValidBillingCycles, default: ValidBillingCycles.monthly })
public billingCycle?: ValidBillingCycles;

/**
 * The amount a customer's wallet is topped up to when their balance falls below the top up threshold.
 * Required, and only allowed, when the `billingCycle` is `topUp`. Only numerical strings greater than zero are allowed.
 * <br><br>Example: `"100.00"` for $100.00.
 * @example "100.00"
 */
@IsNumberString()
@IsOptional()
@Validate(IsNumericStringGreaterToZeroValidator)
@TopUpField('topUpAmount')
public topUpAmount?: string;

/**
 * The percentage, expressed as a decimal, of the `topUpAmount` which triggers a top up of the customer's wallet.
