 */
public getTopUpThresholdAmount(): number {
    const topUpAmount = this.topUpAmount ? parseFloat(this.topUpAmount) : 0;
    const topUpThreshold = parseFloat(this.topUpThreshold ? this.topUpThreshold : DEFAULT_TOP_UP_THRESHOLD);
    return topUpThreshold * topUpAmount;
