/**
 * Registers a single hourly scheduler for the offering, this scheduler is shared between all
 * customers which are enrolled in the top up offering.
 */
protected async registerTopUpSchedule(subject: string): Promise<void> {
    Offering.logger.log(
        `Registering top up schedule for offering: ${this.offeringId} for business: ${this.businessID}`,
    );
    await this.schedulerService.create({
