/**
 * Validates the prepaid credit top up fields on an offering.
 *
 * A `topUpAmount` is required for offerings with a `topUp` billing cycle, the top up fields are not allowed on
 * offerings with any other billing cycle, and subscription offerings cannot use the `topUp` billing cycle.
 */
public static validateTopUpFields({
    billingCycle,
    offeringType,
    topUpAmount,
    topUpThreshold,
}: {
    billingCycle?: ValidBillingCycles;
    offeringType?: string;
    topUpAmount?: string;
    topUpThreshold?: string;
}): void {
    const isTopUp = billingCycle === ValidBillingCycles.topUp;
    if (!isTopUp) {
        if (topUpAmount !== undefined && topUpAmount !== null) {
            throw new BadRequestException(
                'topUpAmount is only supported on offerings with a topUp billing cycle',
            );
        }
        if (topUpThreshold !== undefined && topUpThreshold !== null) {
            throw new BadRequestException(
                'topUpThreshold is only supported on offerings with a topUp billing cycle',
            );
        }
        return;
    }
    if (offeringType === OfferingType.subscription) {
        throw new BadRequestException('The topUp billing cycle is not supported for subscription offerings');
    }
    if (topUpAmount === undefined || topUpAmount === null || `${topUpAmount}`.trim() === '') {
        throw new BadRequestException('topUpAmount is required for offerings with a topUp billing cycle');
    }
    if (isNaN(Number(topUpAmount)) || Number(topUpAmount) <= 0) {
        throw new BadRequestException(
            `topUpAmount is invalid: ${topUpAmount} must be a number greater than zero in string format`,
        );
    }
    if (topUpThreshold !== undefined && topUpThreshold !== null) {
        if (isNaN(Number(topUpThreshold)) || Number(topUpThreshold) < 0) {
            throw new BadRequestException(
                `topUpThreshold is invalid: ${topUpThreshold} must be a number greater than or equal to zero in string format`,
            );
        }
    }
}

