import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { aggregationInterval, aggregationMethod, countBasedUnits, roundingEnum } from '../../dimensions/dto/create-dimension.dto.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { SupportedMeasurementFrequencies } from '../../scheduler/dto/scheduler.dto.js';
import { DatetimeUtils } from '../../utils/datetime.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';
import { CreditService } from '../../credit/credit.service.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';

describe('Top Up Offerings', () => {
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    let creditService: CreditService;
    let topUpOffering: ReadOfferingResponseData;
    let customer: ReadCustomerResponseData;
    const fakeBusinessID = 'fakeBusinessID';
    const fakeCustomerID = 'fakeCustomerID';
    const fakeOfferingId = 'fakeOfferingId';
    const dimensionId = '123';
    const fakeSettings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;

    const buildOffering = (overrides: Partial<ReadOfferingResponseData> = {}) =>
        Offering.getInstance(
            { ...topUpOffering, ...overrides },
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
            undefined,
            undefined,
            creditService,
        );

    const mockUsage = (value: string) => {
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId,
                            usage: [
                                {
                                    startTime: DatetimeUtils.oneHourBefore(new Date()).toISOString(),
                                    endTime: new Date().toISOString(),
                                    value,
                                },
                            ],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );
    };

    beforeEach(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        creditService = new CreditService();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({ invoiceId: '123', message: 'foobar' }));
        jest.spyOn(invoicesService, 'queueInvoice').mockImplementation(async () => ({ message: 'foobar' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'consolidateInvoice').mockImplementation(async () => ({ invoiceId: '123' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({ data: [] }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(creditService, 'create').mockImplementation(async () => ({ message: 'created' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'create').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'emitOne').mockImplementation(async () => ({}));

        topUpOffering = {
            offeringId: fakeOfferingId,
            offeringName: 'foobar',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            billingCycle: ValidBillingCycles.topUp,
            topUpAmount: '100',
            dimensions: [
                {
                    dimensionId,
                    dimensionName: 'fake',
                    usageIncrement: '1',
                    aggregationInterval: aggregationInterval.day,
                    aggregationMethod: aggregationMethod.sum,
                    consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
                    rounding: roundingEnum.ceiling,
                    consumptionPrice: '1',
                },
            ],
        } as unknown as ReadOfferingResponseData;

        customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
            creditBalance: '0',
        } as ReadCustomerResponseData;
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    test('The default top up threshold is 0.2 of the top up amount', () => {
        const offering = buildOffering();
        expect(offering.topUpThreshold).toEqual('0.2');
        expect(offering.getTopUpThresholdAmount()).toEqual(20);
    });

    test('Enrollment registers a single offering level hourly scheduler', async () => {
        const offering = buildOffering();
        await offering.enroll('fakeSubject', customer);
        expect(schedulerService.create).toBeCalledTimes(1);
        expect(schedulerService.create).toBeCalledWith(
            expect.objectContaining({
                rate: SupportedMeasurementFrequencies.everyHour,
                schedulerID: expect.not.stringContaining(fakeCustomerID),
                scheduleParameters: expect.objectContaining({
                    businessID: fakeBusinessID,
                    offeringId: fakeOfferingId,
                }),
            }),
        );
        // Every customer of the offering shares the same scheduler
        const secondOffering = buildOffering();
        await secondOffering.enroll('fakeSubject', { ...customer, customerId: 'anotherCustomer' });
        const [[firstCall], [secondCall]] = (schedulerService.create as jest.Mock).mock.calls;
        expect(firstCall.schedulerID).toEqual(secondCall.schedulerID);
    });

    test('Enrollment fills the customer wallet up to the top up amount', async () => {
        const offering = buildOffering();
        await offering.enroll('fakeSubject', customer);
        expect(invoicesService.create).toBeCalledTimes(1);
        expect(invoicesService.create).toBeCalledWith(
            expect.objectContaining({
                storePaymentAsCredit: true,
                items: {
                    lineItems: [{ name: 'foobar - Top Up', quantity: 1, unitCost: 100, description: undefined }],
                },
            }),
        );
    });

    test('A balance exactly at the threshold is treated as sufficient', async () => {
        const offering = buildOffering();
        await offering.topUp({ customer: { ...customer, creditBalance: '20' } });
        expect(invoicesService.create).toBeCalledTimes(0);
    });

    test('A balance below the threshold charges the gap to the top up amount', async () => {
        const offering = buildOffering();
        await offering.topUp({ customer: { ...customer, creditBalance: '19.5' } });
        expect(invoicesService.create).toBeCalledTimes(1);
        expect(invoicesService.create).toBeCalledWith(
            expect.objectContaining({
                storePaymentAsCredit: true,
                items: {
                    lineItems: [{ name: 'foobar - Top Up', quantity: 1, unitCost: 80.5, description: undefined }],
                },
            }),
        );
    });

    test('Hourly usage is deducted from the wallet, even when it exceeds the balance, without a usage invoice', async () => {
        mockUsage('150');
        const offering = buildOffering();
        const balancedCustomer = { ...customer, creditBalance: '100' };
        await offering.processTopUpUsage({ customer: balancedCustomer, creditService });
        expect(creditService.create).toBeCalledTimes(1);
        expect(creditService.create).toBeCalledWith(
            expect.objectContaining({
                transactionAmount: '-150.00',
                customerId: fakeCustomerID,
                businessID: fakeBusinessID,
            }),
        );
        // The in memory balance is updated, and used for the top up evaluation
        expect(balancedCustomer.creditBalance).toEqual('-50');
        expect(invoicesService.create).toBeCalledTimes(1);
        expect(invoicesService.create).toBeCalledWith(
            expect.objectContaining({
                storePaymentAsCredit: true,
                items: {
                    lineItems: [{ name: 'foobar - Top Up', quantity: 1, unitCost: 150, description: undefined }],
                },
            }),
        );
    });

    test('Zero usage does not create a credit transaction but still evaluates the top up', async () => {
        mockUsage('0');
        const offering = buildOffering();
        await offering.processTopUpUsage({ customer: { ...customer, creditBalance: '50' }, creditService });
        expect(creditService.create).toBeCalledTimes(0);
        expect(invoicesService.create).toBeCalledTimes(0);

        await offering.processTopUpUsage({ customer: { ...customer, creditBalance: '5' }, creditService });
        expect(creditService.create).toBeCalledTimes(0);
        expect(invoicesService.create).toBeCalledTimes(1);
    });

    test('Processing billing on a top up offering deducts usage and never creates a usage invoice', async () => {
        mockUsage('30');
        const offering = buildOffering();
        await offering.processBilling(undefined, undefined, { ...customer, creditBalance: '100' });
        expect(creditService.create).toBeCalledTimes(1);
        expect(creditService.create).toBeCalledWith(
            expect.objectContaining({ transactionAmount: '-30.00' }),
        );
        // A balance of 70 is above the threshold of 20, so no invoice is created
        expect(invoicesService.create).toBeCalledTimes(0);
    });

    test('Unenrollment from a top up offering does not bill the customer or remove the shared scheduler', async () => {
        const offering = buildOffering();
        jest.spyOn(schedulerService, 'remove').mockImplementation(async () => ({ message: 'removed', data: [] }));
        await offering.unenroll({ customer });
        expect(invoicesService.create).toBeCalledTimes(0);
        expect(schedulerService.remove).toBeCalledTimes(0);
    });
});

import { BadRequestException } from '@nestjs/common';
import { CreateOfferingDTO, ValidBillingCycles } from './dto/createOffering.dto.js';
import { OfferingService } from './offering.service.js';
import { OfferingPackageEntity } from './entities/offeringPackage.entity.js';
import { OfferingType } from './entities/OfferingType.js';

describe('Top Up Offering Contract', () => {
    describe('validation', () => {
        it('requires a top up amount for offerings with a topUp billing cycle', () => {
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.topUp,
                    offeringType: OfferingType.usageBased,
                }),
            ).toThrow(BadRequestException);
        });
        it('does not allow the top up fields on other billing cycles', () => {
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.monthly,
                    offeringType: OfferingType.usageBased,
                    topUpAmount: '100',
                }),
            ).toThrow(BadRequestException);
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.annualToDate,
                    offeringType: OfferingType.usageBased,
                    topUpThreshold: '0.5',
                }),
            ).toThrow(BadRequestException);
        });
        it('does not allow subscription offerings to use the topUp billing cycle', () => {
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.topUp,
                    offeringType: OfferingType.subscription,
                    topUpAmount: '100',
                }),
            ).toThrow(BadRequestException);
        });
        it('allows a valid top up offering', () => {
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.topUp,
                    offeringType: OfferingType.usageBased,
                    topUpAmount: '100',
                    topUpThreshold: '0.5',
                }),
            ).not.toThrow();
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.monthly,
                    offeringType: OfferingType.usageBased,
                }),
            ).not.toThrow();
        });
    });

    describe('persistence', () => {
        it('defaults the top up threshold to 0.2 and persists the top up fields', () => {
            const tag = jest.fn();
            const influxService = {
                getPoint: () => ({ tag, stringField: jest.fn() }),
                //eslint-disable-next-line
                //@ts-ignore
            } as any;
            const entity = new OfferingPackageEntity({
                offeringName: 'foobar',
                businessID: 'fakeBusinessID',
                offeringId: 'fakeOfferingId',
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
            } as OfferingPackageEntity);
            expect(entity.topUpAmount).toEqual('100');
            expect(entity.topUpThreshold).toEqual('0.2');
            OfferingPackageEntity.transformer(entity, influxService);
            expect(tag).toHaveBeenCalledWith('topUpAmount', '100');
            expect(tag).toHaveBeenCalledWith('topUpThreshold', '0.2');
        });
        it('reads the top up fields back out of the database model', () => {
            const entity = OfferingPackageEntity.dbModelToEntity({
                _value: 'foobar',
                billingCycle: ValidBillingCycles.topUp,
                businessID: 'fakeBusinessID',
                offeringId: 'fakeOfferingId',
                offeringType: OfferingType.usageBased,
                subscriptionPrice: '0',
                topUpAmount: '250',
                topUpThreshold: '0.5',
            });
            const dto = new CreateOfferingDTO(entity);
            expect(dto.topUpAmount).toEqual('250');
            expect(dto.topUpThreshold).toEqual('0.5');
        });
        it('does not set the top up fields for other billing cycles', () => {
            const entity = new OfferingPackageEntity({
                offeringName: 'foobar',
                businessID: 'fakeBusinessID',
                offeringId: 'fakeOfferingId',
                billingCycle: ValidBillingCycles.monthly,
            } as OfferingPackageEntity);
            expect(entity.topUpAmount).toBeUndefined();
            expect(entity.topUpThreshold).toBeUndefined();
        });
    });
});

