getCronRate(): string {
    if (this.billingCycle === ValidBillingCycles.monthly) {
        return SupportedMeasurementFrequencies.monthly as unknown as string;
    } else if (this.billingCycle === ValidBillingCycles.annualToDate) {
        return DatetimeUtils.dateToAnnualCronString(new Date());
    } else if (this.billingCycle === ValidBillingCycles.topUp) {
        return SupportedMeasurementFrequencies.everyHour as unknown as string;
    }
}

/**
 * Determines if the offering is a prepaid credit, top up, offering.
 */
public isTopUpOffering(): boolean {
    return this.billingCycle === ValidBillingCycles.topUp;
}

/**
 * The stable offering level schedulerID used for the hourly top up scheduler.
 * A single scheduler is created per top up offering, and is shared by every customer enrolled in the offering.
 */
public static getTopUpSchedulerId(offeringId: string): string {
    return `${offeringId}#top-up`;
}

/**
 * The amount of credit which must be in a customer's wallet before the wallet is topped up.
 */
public getTopUpThresholdAmount(): number {
    const topUpAmount = this.topUpAmount ? parseFloat(this.topUpAmount) : 0;
    const topUpThreshold = parseFloat(this.topUpThreshold ? this.topUpThreshold : DEFAULT_TOP_UP_THRESHOLD);
    return topUpThreshold * topUpAmount;
}

/**
 * Registers a single hourly scheduler for the offering, this scheduler is shared between all
 * customers which are enrolled in the top up offering.
 */
protected async registerTopUpSchedule(subject: string): Promise<void> {
    Offering.logger.log(
        `Registering top up schedule for offering: ${this.offeringId} for business: ${this.businessID}`,
    );
    await this.schedulerService.create({
        schedulerID: Offering.getTopUpSchedulerId(this.offeringId),
        schedulerType: schedulerType.dimensionDataGathering,
        schedulerStatus: SchedulerStatus.live,
        scheduleParameters: {
            businessID: this.businessID,
            offeringId: this.offeringId,
            dimensionType: OFFERING_TOP_UP_CHECKER,
        } as OfferingTopUpCheckerDto,
        rate: this.getCronRate(),
        subject,
        businessID: this.businessID,
    });
}

/**
 * Tops up the customer's wallet back up to the `topUpAmount` when the current wallet balance has fallen
 * below `topUpThreshold * topUpAmount`. A balance which is exactly at the threshold is considered sufficient.
 *
 * The charge is made through an invoice whose payment is stored as credit on the customer's wallet.
 */
public async topUp({ customer }: { customer?: ReadCustomerResponseData }): Promise<string | void> {
    if (!this.isTopUpOffering() || !this.topUpAmount) {
        Offering.logger.warn(
            `Top up requested for offering ${this.offeringId} which is not a top up offering. Skipping.`,
        );
        return;
    }
    const topUpAmount = parseFloat(this.topUpAmount);
    const thresholdAmount = this.getTopUpThresholdAmount();
    const currentBalance = Offering.parseBalance(customer?.creditBalance);
    Offering.logger.log(
        `Evaluating top up for customer: ${
            customer?.customerId ? customer?.customerId : this.customerId
        }, balance: ${currentBalance}, threshold: ${thresholdAmount}, topUpAmount: ${topUpAmount}`,
    );
    if (currentBalance >= thresholdAmount) {
        // The customer has enough credit in their wallet, nothing to do.
        return;
    }
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, topUpAmount - currentBalance));
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId: customer?.customerId ? customer?.customerId : this.customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

/**
 * Deducts the usage which occurred in the given time range from the customer's wallet, and then evaluates
 * if the customer's wallet should be topped up with the updated balance.
 *
 * The usage is always fully deducted from the wallet, even when the usage exceeds the current balance,
 * and does not generate a usage invoice.
 */
public async processTopUpUsage({
    customer,
    creditService,
    startDate,
    endDate,
}: {
    customer: ReadCustomerResponseData;
    creditService?: CreditService;
    startDate?: Date;
    endDate?: Date;
}): Promise<{ usageAmount: number; balance: number; invoiceId?: string | void }> {
    const endTime = endDate ? endDate : new Date();
    const startTime = startDate ? startDate : DatetimeUtils.oneHourBefore(endTime);
    const creditServiceToUse = creditService ? creditService : this.getCreditService();
    const lineItems = await Offering.getLineItemsForUsage({
        startDate: startTime,
        endDate: endTime,
        customer,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID: this.businessID,
        customerId: customer?.customerId ? customer?.customerId : this.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageAmount = lineItems.getTotal();
    let balance = Offering.parseBalance(customer?.creditBalance);
    Offering.logger.log(
        `Top up usage for customer: ${
            customer?.customerId ? customer?.customerId : this.customerId
        } between ${startTime.toISOString()} and ${endTime.toISOString()} is ${usageAmount}. Current balance: ${balance}`,
    );
    if (usageAmount > 0) {
        if (creditServiceToUse) {
            await creditServiceToUse.create({
                transactionAmount: (usageAmount * -1).toFixed(2),
                customerId: customer?.customerId ? customer?.customerId : this.customerId,
                businessID: this.businessID,
                timestamp: endTime.toISOString(),
                metadata: {
                    reason: `Usage for ${this.offeringName}`,
                    offeringId: this.offeringId,
                },
                // Usage is always fully deducted from the wallet, even when it exceeds the current balance
                allowNegativeBalance: true,
            });
        } else {
            AuditService.publishEvent({
                message: 'Failed to deduct top up usage from customer wallet, no credit service available',
                topic: AuditScope.ERROR,
                data: [
                    {
                        businessID: this.businessID,
                        customerId: customer?.customerId ? customer?.customerId : this.customerId,
                        offeringId: this.offeringId,
                    },
                ],
            });
        }
        // The in memory balance is updated so that the top up evaluation uses the updated balance
        balance = balance - usageAmount;
        if (customer) {
            customer.creditBalance = balance.toString();
        }
    }
    const invoiceId = await this.topUp({ customer });
    return { usageAmount, balance, invoiceId };
}

protected getCreditService(): CreditService | undefined {
    if (this.creditService) {
        return this.creditService;
    }
    return this.invoicesService?.creditService;
}

static parseBalance(balance?: string | number): number {
    if (balance === undefined || balance === null || balance === '') {
        return 0;
    }
    const parsed = typeof balance === 'number' ? balance : parseFloat(balance);
    return isNaN(parsed) ? 0 : parsed;
}

